  "Dans les prochains jours (réglable). Le chauffeur ou le bateau ne sait pas quand passer.": "In the next few days (adjustable). The driver or the boat does not know when to come.",
  "Services à venir sans lieu de pickup": "Upcoming services without a pickup place",
  "Dans les prochains jours (réglable). Ni lieu de pickup sur la réservation, ni hôtel sur la fiche du client.": "In the next few days (adjustable). No pickup place on the booking and no hotel on the client's record.",
  "Services à venir sans prix": "Upcoming services without a price",
  "Services à venir sans net": "Upcoming services without a net price",
  "Payés chez nous, sans net prévu : la marge et ce que l'on doit au prestataire ne se calculent pas. Un service dont un des nets manque (adulte ou enfant) reste ici jusqu'à ce que le net total soit saisi.": "Paid to us, with no planned net: the margin and what we owe the provider cannot be worked out. A service missing one of its nets (adult or child) stays here until the total net is entered.",
  "Services à venir sans commission": "Upcoming services without a commission",
  "Payés sur place au prestataire, sans commission prévue : rien ne rappellera de la lui demander. Saisissez-la ici.": "Paid on site to the provider, with no planned commission: nothing will remind you to ask for it. Enter it here.",
  "Clients peut-être en double": "Possible duplicate clients",
  "Même téléphone, même e-mail ou même prénom et nom. Si c'est la même personne, gardez une fiche et rattachez-y ses dossiers.": "Same phone, same e-mail or same first and last name. If it is the same person, keep one record and move their files to it.",
  "Aucun de leurs numéros n'est noté WhatsApp : leur fiche n'a pas de bouton pour leur écrire. Si l'un des numéros a WhatsApp, indiquez-le sur la fiche.": "None of their numbers is marked WhatsApp: their record has no button to message them. If one of the numbers has WhatsApp, mark it on the record.",
  "Un écart plus grand que le seuil réglé entre « arrivée moins départ » et la durée écrite. Un trajet à plusieurs étapes peut l'expliquer : à relire, pas forcément une erreur.": "A gap larger than the set threshold between “arrival minus departure” and the written duration. A trip with several legs can explain it: to review, not necessarily a mistake.",
  "Réglages de « À vérifier » enregistrés.": "“To check” settings saved.",
  "Pour {nom}. Un contrôle décoché disparaît de l'écran ; il revient dès qu'on le recoche.": "For {nom}. An unticked check disappears from the screen; it comes back as soon as you tick it again.",
