  "Chaque case ajoute un droit. Un droit en suppose d'autres : « modifier » coche automatiquement « voir ».": "Each box adds a right. A right implies others: \"edit\" automatically ticks \"view\".",
  "Chaque devis choisit une de ces variantes, ou son propre texte. Une ligne commençant par « - » devient une puce. **gras**, _italique_. Les mots entre accolades se remplissent seuls : {acompte}, {solde}, {delai}, {total}, {indicatif}.": "Each quote picks one of these variants, or its own text. A line starting with \"-\" becomes a bullet. **bold**, _italic_. Words in braces fill in on their own: {acompte}, {solde}, {delai}, {total}, {indicatif}.",
  "Chaque entreprise a ses propres clients, dossiers, paiements, catalogue, réglages, logo et devise. Personne ne voit une entreprise sans y avoir accès.": "Each company has its own clients, files, payments, catalogue, settings, logo and currency. Nobody sees a company without having access to it.",
