  "Le {date}": "On {date}",
  "le client": "the client",
  "Le client a accepté": "The client accepted",
  "Le client a accepté le devis": "The client accepted the quote",
  "le contenu": "the content",
  "le document": "the document",
  "Le document est copié avec toutes ses lignes, sans paiement ni date d'envoi. Créez d'abord le client s'il n'existe pas encore.": "The document is copied with all its lines, without payments or sent date. Create the client first if they do not exist yet.",
  "le dossier": "the file",
  "Le facturé": "The invoiced amount",
  "Le journal d'activité est réservé aux personnes qui en ont le droit.": "The activity log is reserved for people who have the right to see it.",
  "Le journal garde la trace des créations, modifications et suppressions. Il ne peut être ni modifié ni vidé. Le contenu des réglages (coordonnées bancaires) n'y est jamais recopié.": "The log keeps a record of creations, changes and deletions. It cannot be edited or emptied. The content of the settings (bank details) is never copied into it.",
  "le libellé": "the label",
  "Le libellé, le prix de vente et l'unité viennent de la base partenaires. Le net reste attaché à la ligne pour calculer la marge.": "The label, the sale price and the unit come from the partner database. The net price stays attached to the line to calculate the margin.",
  "Le même voucher se donne au client et au prestataire. Les cases Paid, Deposit ou Pay on site suivent les paiements enregistrés sur la facture. « Modifier » ouvre la réservation avec les champs du voucher : chambre, drop-off, vol, bagages, type de tour ou de transfert, frais de parc, remarques.": "The same voucher is given to the client and to the provider. The Paid, Deposit and Pay on site boxes follow the payments recorded on the invoice. \"Edit\" opens the reservation with the voucher fields: room, drop-off, flight, luggage, type of tour or transfer, park fees, remarks.",
  "Le menu se met à jour après l'enregistrement. Les droits des rôles s'appliquent toujours en plus.": "The menu updates after saving. The rights of the roles still apply on top of this.",
  "le montant": "the amount",
  "le moyen de paiement": "the payment method",
  "le nom": "the name",
  "Le nom de l'entreprise si vide. Ignoré quand une image de titre est choisie.": "The company name if empty. Ignored when a title image is chosen.",
  "le paiement": "the payment",
  "le prénom": "the first name",
  "le prix": "the price",
  "le responsable": "the person in charge",
  "le rôle": "the role",
  "Le tableau analytique est réservé aux rôles qui ont les droits « analyses » et « montants ».": "The analytics are reserved for roles that have the \"analytics\" and \"amounts\" rights.",
  "le téléphone": "the phone number",
  "le titre": "the title",
  "Le total du devis est à zéro.": "The quote total is zero.",
  "Lecteur": "Reader",
  "Lecture de l'image impossible.": "Could not read the image.",
  "Lecture du fichier impossible.": "Could not read the file.",
  "Lecture seule : votre rôle ne permet pas de modifier les clients.": "Read only: your role does not allow you to edit clients.",
  "Lecture seule : votre rôle ne permet pas de modifier les devis et factures. Vous pouvez les consulter et télécharger le PDF.": "Read only: your role does not allow you to edit quotes and invoices. You can view them and download the PDF.",
  "Les clients se créent avec leur premier dossier, ou avec le bouton ci-dessus.": "Clients are created with their first file, or with the button above.",
  "Les compléter": "Complete them",
  "Les dates du dossier sont celles de ses réservations, elles se mettent à jour toutes seules.": "The dates of the file are those of its reservations, they update on their own.",
  "les droits": "the rights",
  "Les formules et les prix que vous reprenez souvent dans les devis. Un prix modifié ici ne change pas les documents déjà créés.": "The packages and prices you often reuse in quotes. A price changed here does not change documents already created.",
  "Les heures de pickup sont sur la fiche de chaque compagnie : ": "Pickup times are on each company's page: ",
  "Les lignes de partenaires du document peuvent devenir des réservations en un clic.": "The partner lines of the document can become reservations in one click.",
  "Les montants en {liste} ne sont pas convertis en {cible} (taux manquant) et n'entrent pas dans les totaux. Indiquez le taux dans la section « Taux de conversion » en bas de page.": "Amounts in {liste} are not converted to {cible} (missing rate) and are not included in the totals. Enter the rate in the \"Conversion rates\" section at the bottom of the page.",
  "Les montants sont ramenés en {cible} à titre indicatif, avec les taux ci-dessous. Chaque société garde ses chiffres exacts dans sa propre devise (écran Analyses).": "Amounts are converted to {cible} for information, with the rates below. Each company keeps its exact figures in its own currency (Analytics screen).",
  "Les mots DEVIS et FACTURE sont des images. Retirez-les pour les remplacer par les textes de l'onglet « Textes ».": "The words QUOTE and INVOICE are images. Remove them to replace them with the texts from the \"Texts\" tab.",
  "les notes": "the notes",
  "Les raccourcis propres au navigateur, comme Ctrl+T, Ctrl+W ou Ctrl+N, ne peuvent pas être pris en charge par un site. Les autres sont désactivés pendant la saisie dans un champ pour ne pas gêner l'écriture.": "Browser shortcuts such as Ctrl+T, Ctrl+W or Ctrl+N cannot be handled by a website. The others are disabled while typing in a field so they do not get in the way.",
  "les réglages": "the settings",
  "Les réglages d'une entreprise sont réservés à ses administrateurs.": "A company's settings are reserved for its administrators.",
  "Les réglages de {nom} ne sont pas terminés : il manque {liste}. ": "The settings of {nom} are not complete. Missing: {liste}. ",
  "Les règles se remplissent depuis la fiche de chaque partenaire.": "The rules are filled in from each partner's page.",
  "Les réservations se créent depuis la fiche d'un dossier, à partir des lignes de partenaires du devis.": "Reservations are created from a file's page, from the partner lines of the quote.",
  "Les tarifs se créent depuis la fiche d'un partenaire ou avec le bouton ci-dessus.": "Rates are created from a partner's page or with the button above.",
  "Les titres, libellés et conditions de paiement passent en anglais. Les textes des lignes (intitulés, descriptions) sont copiés tels quels : à traduire dans l'éditeur.": "Titles, labels and payment terms switch to English. The texts of the lines (titles, descriptions) are copied as they are: translate them in the editor.",
  "Les trajets des compagnies s'importent depuis Réglages, Sauvegarde, ou se créent ici.": "Company routes are imported from Settings, Backup, or created here.",
  "Les variables entre accolades sont remplies d'après la réservation ou le dossier. Les textes thaïs sont des propositions à faire relire avant usage.": "Variables in braces are filled in from the reservation or the file. The Thai texts are suggestions to have checked before real use.",
  "Les vouchers se préparent depuis les réservations du dossier.": "Vouchers are prepared from the reservations of the file.",
  "Les vouchers sont en anglais. Un champ vide reprend la valeur de l'onglet Entreprise (nom, sous-titre, adresse, téléphone) ; le logo est celui de l'onglet Apparence. L'aperçu à droite suit vos modifications.": "Vouchers are in English. An empty field takes the value from the Company tab (name, subtitle, address, phone); the logo is the one from the Appearance tab. The preview on the right follows your changes.",
  "Lettres minuscules, chiffres et tirets. Il ne change plus ensuite.": "Lowercase letters, digits and hyphens. It cannot be changed afterwards.",
