  "Un bloc avec son titre et sa liste de prestations, éventuellement avec un prix par jour.": "A block with its title and its list of services, possibly with a price per day.",
  "Un devis": "A quote",
  "Un document peut être écrit en anglais depuis son en-tête (par exemple la facture locale). Il utilise alors la version anglaise de ces textes.": "A document can be written in English from its header (for example the local invoice). It then uses the English version of these texts.",
  "Un dossier n'a pas pu être modifié : {message}": "A file could not be updated: {message}",
  "Un dossier regroupe le client, le voyage, le devis, la facture et les paiements.": "A file groups the client, the trip, the quote, the invoice and the payments.",
  "Un partenaire regroupe ses contacts, ses tarifs, ses trajets, ses règles et son contrat.": "A partner groups their contacts, rates, routes, rules and contract.",
  "Un rappel apparaît dans Aujourd'hui trente jours avant.": "A reminder appears on the Today screen thirty days before.",
  "Un rôle est un ensemble de droits, défini pour chaque entreprise. Vous pouvez en créer autant que nécessaire (comptable, chauffeur, stagiaire…) et décider précisément ce que chacun voit et peut faire. Les droits d'un rôle s'appliquent tout de suite à toutes les personnes qui l'ont.": "A role is a set of rights, defined for each company. You can create as many as needed (accountant, driver, intern…) and decide precisely what each person sees and can do. The rights of a role apply immediately to everyone who has it.",
  "Un voucher par réservation (les frais de parc n'en ont pas). Créez d'abord les réservations ci-dessous.": "One voucher per reservation (park fees do not have one). First create the reservations below.",
  "Une fois le PDF expédié, notez-le ici pour suivre les relances.": "Once the PDF has been sent, note it here to keep track of follow-ups.",
