  "Dossier restauré.": "File restored.",
  "Dossiers supprimés": "Deleted files",
  "Un dossier supprimé reste récupérable pendant 90 jours, avec ses documents, ses paiements, ses réservations et ses tâches. Les fichiers joints ne sont pas conservés.": "A deleted file can be recovered for 90 days, with its documents, payments, reservations and tasks. Attached files are not kept.",
  "Si le fichier contient les réglages, les restaurer aussi (remplace les textes des documents, les coordonnées de paiement et la numérotation actuels)": "If the file contains the settings, restore them too (replaces the current document texts, payment details and numbering)",
  "Quelqu'un d'autre a enregistré les réglages pendant que vous les modifiiez. Rechargez la page pour voir sa version, puis refaites vos changements.": "Someone else saved the settings while you were editing them. Reload the page to see their version, then redo your changes.",
