  "Document restauré.": "Document restored.",
  "Devis et factures supprimés": "Deleted quotes and invoices",
  "Un devis ou une facture supprimé seul reste ici 90 jours. « Restaurer » le remet dans son dossier, tel qu'il était.": "A quote or invoice deleted on its own stays here for 90 days. “Restore” puts it back into its file, as it was.",
  "Noms et symboles des devises, une par ligne : code | nom | symbole": "Currency names and symbols, one per line: code | name | symbol",
  "Le nom remplace {devise_nom} dans les conditions de paiement, le symbole s'affiche dans les équivalents. Vide : les valeurs grisées.": "The name replaces {devise_nom} in the payment terms, the symbol shows in the equivalents. Empty: the greyed-out values.",
  "Facture pas encore prête à partir": "Invoice not ready to send yet",
  "Ces lignes n'ont pas de prix. Indiquez un prix, ou cochez « Offert » si le service est offert au client :": "These lines have no price. Enter a price, or tick “Complimentary” if the service is free for the client:",
