  "Le document reste 90 jours dans la corbeille des devis et factures (Réglages, onglet Sauvegarde) et peut être restauré.": "The document stays in the quotes and invoices trash for 90 days (Settings, Backup tab) and can be restored.",
  "Acompte non figé sur le dossier : {message}": "Deposit not locked on the file: {message}",
  "Acceptation non enregistrée : {message}": "Acceptance not saved: {message}",
  "Un document est déjà parti chez le client avec le numéro {ref}. Le changer renumérote le devis, la facture et les vouchers de ce dossier : le client aura deux numéros pour le même dossier. Le changer quand même ?": "A document has already gone to the client with number {ref}. Changing it renumbers this file's quote, invoice and vouchers: the client will have two numbers for the same file. Change it anyway?",
  "Changer le numéro": "Change the number",
  "Document déjà envoyé : le numéro ne change plus.": "Document already sent: the number no longer changes.",
  "Document envoyé : le numéro ne change plus.": "Document sent: the number no longer changes.",
  "La facture envoyée indique {imprime} reçus. Les paiements enregistrés font {paiements}. Mettre {paiements} sur la facture renvoyée ?": "The invoice that was sent shows {imprime} received. The recorded payments add up to {paiements}. Put {paiements} on the resent invoice?",
  "Mettre à jour le montant reçu": "Update the amount received",
  "modifié depuis l'envoi": "changed since sent",
