  "Supprimer ce dossier avec ses documents, ses paiements et ses réservations ? Il reste 90 jours dans la corbeille (Réglages, onglet Sauvegarde) et peut être restauré pendant ce temps.": "Delete this file with its documents, payments and bookings? It stays in the trash for 90 days (Settings, Backup tab) and can be restored during that time.",
  "Supprimer ce dossier avec ses documents et ses paiements ? En démonstration, il ne peut pas être restauré.": "Delete this file with its documents and payments? In demo mode it cannot be restored.",
  "Version envoyée au client le {date}": "Version sent to the client on {date}",
  "Ce document est déjà parti chez le client avec le numéro {numero}. Changer le numéro donne au client deux documents différents pour le même service. Le changer quand même ?": "This document has already gone to the client with number {numero}. Changing the number gives the client two different documents for the same service. Change it anyway?",
