  "autre": "other",
  "Non précisé": "Not specified",
  "Valeur des services vendus sur la période, y compris ceux que le client paie directement au prestataire. Dossiers acceptés ou facturés, hors dossiers annulés. La date retenue est celle de la facture, sinon celle de l'acceptation, sinon celle du devis.": "Value of the services sold in the period, including those the client pays directly to the provider. Files that are accepted or invoiced, cancelled files excluded. The date used is the invoice date, otherwise the acceptance date, otherwise the quote date.",
  "Total à régler chez nous des factures émises sur la période, hors dossiers annulés. Les services payés sur place n'y sont pas, car le client ne nous les paie pas.": "Amount payable to us on the invoices issued in the period, cancelled files excluded. Services paid on the spot are not included: the client does not pay us for them.",
  "Argent passé par nous, c'est-à-dire les paiements des clients datés de la période, remboursements déduits. Les écarts soldés (frais, change) n'y sont pas : ils sont comptés à part.": "Money that went through us: client payments dated in the period, refunds deducted. Settled differences (fees, exchange) are not included: they are counted separately.",
  "Écarts soldés": "Settled differences",
  "Petits restes soldés sans que l'argent arrive chez nous (frais Wise, change), datés de la période. Le dossier est soldé, mais ces montants ne sont pas de l'encaissé.": "Small balances settled without the money reaching us (Wise fees, exchange), dated in the period. The booking is settled, but these amounts are not money received.",
  "Ce que les clients nous doivent encore sur les factures émises, à ce jour. Les services payés sur place n'entrent pas dans ce chiffre.": "What clients still owe us on issued invoices, as of today. Services paid on the spot are not part of this figure.",
  "Devis datés de la période, quel que soit leur sort.": "Quotes dated in the period, whatever became of them.",
  "Parmi les devis émis sur la période, ceux dont le dossier est accepté. Le taux est la part des devis émis.": "Of the quotes issued in the period, those whose file is accepted. The rate is the share of quotes issued.",
  "Devis ni acceptés, ni facturés, ni annulés, à ce jour. C'est le chiffre d'affaires possible.": "Quotes that are not accepted, invoiced or cancelled, as of today. This is the possible turnover.",
  "Dossiers ouverts": "Files opened",
  "Dossiers dont la date de référence tombe dans la période, annulés compris. Sert au taux d'annulation.": "Files whose reference date falls in the period, cancelled ones included. Used for the cancellation rate.",
  "Dossiers annulés": "Cancelled files",
  "Dossiers annulés dont la date de référence tombe dans la période.": "Cancelled files whose reference date falls in the period.",
  "Départs à venir": "Upcoming departures",
  "Dossiers acceptés ou facturés dont le départ est à venir.": "Accepted or invoiced files whose departure is still to come.",
  "Réservations auprès des partenaires dont la date de service tombe dans la période, hors annulées. Le montant est le prix de vente.": "Bookings with partners whose service date falls in the period, cancelled ones excluded. The amount is the selling price.",
  "Services payés chez nous": "Services paid to us",
  "Services dont le client nous paie le prix. Nous réglons ensuite le net au partenaire.": "Services where the client pays us the price. We then settle the net price with the partner.",
