  "Déjà facturé, mais le calcul ne permet plus de dire ce qui revient à l'agence. Corrigez la réservation ou ses montants, puis un avoir se proposera.": "Already invoiced, but the calculation can no longer say what comes back to the agency. Fix the reservation or its amounts, then a credit note will be proposed.",
