  "Une facture par service, adressée à l'entreprise prestataire, pour la seule part qui revient à l'agence : la commission reçue, ou la marge quand le client a payé chez nous. Jamais ce que le client a payé en tout.": "One invoice per service, addressed to the provider company, for the agency's share only: the commission received, or the margin when the client paid us. Never what the client paid in total.",
