  "Exemple de numéros, {facture} pour une facture et {avoir} pour un avoir.": "Sample numbers, {facture} for an invoice and {avoir} for a credit note.",
  "Un préfixe ne contient que des lettres, des chiffres ou des tirets (12 au plus).": "A prefix only contains letters, digits or hyphens (12 at most).",
  "Les factures et les avoirs ont chacun leur préfixe.": "Invoices and credit notes each need their own prefix.",
  "Arrêter les factures pour la fiduciaire dans {entreprise} ? Plus aucune facture ne sera proposée ; celles déjà émises restent et se corrigent par un avoir.": "Stop accountant invoices in {entreprise}? No invoice will be suggested any more; those already issued stay and are corrected with a credit note.",
  "Arrêter": "Stop",
  "Changer de préfixe démarre une nouvelle série de numéros, à partir de 1. Les factures déjà émises gardent leur numéro. Continuer ?": "Changing the prefix starts a new number series, from 1. Invoices already issued keep their number. Continue?",
  "Réglages de la fiduciaire enregistrés.": "Accountant settings saved.",
  "Réglages des factures pour la fiduciaire": "Accountant invoice settings",
  "{entreprise} émet des factures pour la fiduciaire": "{entreprise} issues invoices for the accountant",
  "Case décochée, aucune facture n'est proposée dans cette entreprise. Ce qui a déjà été facturé reste ici et se corrige par un avoir.": "When unticked, no invoice is suggested in this company. Anything already invoiced stays here and is corrected with a credit note.",
  "Un service reçu avant cette date et jamais facturé n'est pas proposé. Laissée vide, la date ne limite rien.": "A service received before this date and never invoiced is not suggested. Left empty, the date sets no limit.",
  "Pour un service payé sur place, la commission reçue du prestataire.": "For a service paid on site, the commission received from the provider.",
  "Pour un service payé chez nous, la marge (prix de vente moins net payé).": "For a service paid to us, the margin (sale price minus net paid).",
  "L'émetteur est {nom}. Son identité, son compte bancaire et son QR code se règlent dans Réglages. Ils sont copiés sur chaque facture le jour de l'émission, les changer ensuite ne modifie pas les factures déjà émises.": "The issuer is {nom}. Its identity, bank account and QR code are set in Settings. They are copied onto each invoice on the day it is issued, so changing them later does not alter invoices already issued.",
  "Les textes de la facture sont en anglais, la fiduciaire les lit tels quels. Un champ vide reprend le texte par défaut.": "The invoice texts are in English, the accountant reads them as they are. An empty field uses the default text.",
  "{entreprise} n'émet pas de factures pour la fiduciaire. Ce qui a déjà été facturé reste ici et se corrige par un avoir.": "{entreprise} does not issue invoices for the accountant. Anything already invoiced stays here and is corrected with a credit note.",
  // Chaque entreprise ses éléments (12.11.2026)
  "Valeur des services dont la date de service tombe dans la période.": "Value of the services whose service date falls in the period.",
  "Le client paie le chauffeur, le revenu vient donc des commissions reçues.": "The client pays the driver, so the revenue comes from the commissions received.",
  "Cette section se remplit avec les réservations auprès des partenaires. Elles se créent depuis une facture, ou à la main.": "This section fills up with bookings made with partners. They are created from an invoice, or by hand.",
  "Cette section se remplit avec les réservations auprès des partenaires. Elles se créent depuis une réservation, ou à la main.": "This section fills up with bookings made with partners. They are created from a booking, or by hand.",
  "sans objet": "not applicable",
  "Pour {liste}, le facturé et la part ne comptent pas les services payés sur place au prestataire.": "For {liste}, the invoiced amount and the share exclude services paid on the spot to the provider.",
  "Pour {liste}, il n'y a pas de facture client (le client paie le chauffeur), donc ni facturé, ni impayés, ni facture moyenne.": "For {liste}, there is no client invoice (the client pays the driver), so no invoiced amount, no unpaid invoices and no average invoice.",
  "Dossiers, réservations et paiements.": "Files, bookings and payments.",
