  "Affiché sous l'adresse sur les factures et sur les vouchers (sauf si le bloc Vouchers a le sien).": "Shown under the address on invoices and vouchers (unless the Vouchers block has its own).",
  "Utile quand certaines factures se paient ailleurs. Chaque facture choisit les informations à afficher.": "Useful when some invoices are paid elsewhere. Each invoice chooses the details to show.",
  "Chaque facture choisit une de ces variantes, ou son propre texte. Une ligne commençant par « - » devient une puce. **gras**, _italique_. Les mots entre accolades se remplissent seuls : {delai}, {total}.": "Each invoice picks one of these variants, or its own text. A line starting with “-” becomes a bullet. **bold**, _italic_. Words in braces fill in by themselves: {delai}, {total}.",
