  "Le partenaire qui reçoit les courses saisies sur l'écran de saisie, les courses hors catalogue et les demandes collées. Sa commission est demandée chaque jour.": "The partner who receives rides entered on the voucher entry screen, rides not in the catalogue and pasted requests. Its commission is requested every day.",
  "Commissions à demander : jusqu'à combien de jours en arrière": "Commissions to request: how many days back",
  "Vide : toutes les courses passées sans commission saisie restent dans la liste, même anciennes.": "Empty: every past ride without a commission entered stays in the list, even old ones.",
  "Booking confirmation modifiée depuis l'envoi du {date} : renvoyez-la au client.": "Booking confirmation changed since it was sent on {date}: resend it to the client.",
  "Voucher modifié depuis l'envoi du {date} : renvoyez-le au client.": "Voucher changed since it was sent on {date}: resend it to the client.",
  "Ce service n'a pas de voucher : il ne figure ni dans les envois ni dans les PDF.": "This service has no voucher: it appears neither in sendings nor in PDFs.",
  "Automatique : déduit de la prestation et du libellé. Choisissez-le quand la déduction se trompe, ou « Pas de voucher » pour une option.": "Automatic: deduced from the service and its name. Choose it when the guess is wrong, or “No voucher” for an option.",
  "Imprimée sur le voucher, dans Remarks (« Operator ref. »).": "Printed on the voucher, in Remarks (“Operator ref.”).",
  "Modifié depuis l'envoi du {date} : renvoyez cette version au client.": "Changed since it was sent on {date}: resend this version to the client.",
