  "Supprimer un partenaire, une prestation ou un trajet": "Delete a partner, a service or a route",
  "Seulement ce qu'aucun service n'utilise. Sans ce droit, on peut toujours masquer.": "Only what no booking uses. Without this right, items can still be hidden.",
  "prix à saisir": "price to enter",
  "Tarif par adulte sans prix enfant : les enfants ne sont pas facturés. Ajoutez le prix enfant dans la fiche de la prestation si besoin.": "Per-adult rate with no child price: children are not charged. Add the child price to the service if needed.",
  "Tarif par adulte sans prix enfant : les enfants ne sont pas comptés.": "Per-adult rate with no child price: children are not counted.",
