  "Ce partenaire est masqué : ni lui, ni ses tarifs, ni ses trajets ne sont proposés pour les nouvelles saisies. Les services déjà enregistrés, leurs factures et leurs vouchers ne changent pas.": "This partner is hidden: neither the partner nor its rates or routes are offered for new bookings. Existing bookings, their invoices and their vouchers do not change.",
  "Réactiver ce partenaire": "Bring this partner back",
  "Aucune grille de pickup. Une grille donne l'heure de pickup de chaque zone pour chaque départ.": "No pickup table. A table gives the pickup time for each area and each departure.",
