  "Masquer ce partenaire": "Hide this partner",
  "Masquer « {nom} » ? Ni lui, ni ses tarifs, ni ses trajets ne seront proposés pour les nouvelles saisies. Les services déjà enregistrés, leurs factures et leurs vouchers ne changent pas. Vous pourrez le réactiver depuis la liste, avec « Afficher les partenaires masqués ».": "Hide “{nom}”? Neither the partner nor its rates or routes will be offered for new bookings. Existing bookings, their invoices and their vouchers do not change. You can bring it back from the list with “Show hidden partners”.",
  "Masquer": "Hide",
  "Partenaire réactivé.": "Partner brought back.",
  "Partenaire masqué.": "Partner hidden.",
  "« {nom} » a {n} service enregistré. Le supprimer retirerait l'opérateur de ce service, de son voucher et des commissions. Masquez-le plutôt : il ne sera plus proposé et ce qui existe ne change pas.": "“{nom}” has {n} booking. Deleting it would remove the operator from that booking, its voucher and the commissions. Hide it instead: it will no longer be offered and nothing that exists changes.",
  "« {nom} » a {n} services enregistrés. Le supprimer retirerait l'opérateur de ces services, de leurs vouchers et des commissions. Masquez-le plutôt : il ne sera plus proposé et ce qui existe ne change pas.": "“{nom}” has {n} bookings. Deleting it would remove the operator from those bookings, their vouchers and the commissions. Hide it instead: it will no longer be offered and nothing that exists changes.",
  "Supprimer définitivement « {nom} » ? Partent avec lui : {tarifs}, {trajets}, leurs prix nets, ses coordonnées bancaires et ses commissions. {taches} Aucun service n'est enregistré avec lui. Cette suppression ne peut pas être annulée : pour le garder sans le proposer, masquez-le.": "Delete “{nom}” for good? These go with it: {tarifs}, {trajets}, their net prices, its bank details and its commissions. {taches} No booking uses it. This cannot be undone: to keep it without offering it, hide it.",
  "Sa tâche reste, sans partenaire.": "Its task stays, without a partner.",
  "Ses {n} tâches restent, sans partenaire.": "Its {n} tasks stay, without a partner.",
