  "« {libelle} » est utilisée par {n} service. La supprimer retirerait à ce service son type de voucher, ses horaires et ses frais de parc. Masquez-la plutôt : elle ne sera plus proposée et ce qui existe ne change pas.": "“{libelle}” is used by {n} booking. Deleting it would remove that booking's voucher type, times and park fees. Hide it instead: it will no longer be offered and nothing that exists changes.",
