  "Vide : « toute la période du contrat » quand il n'y a pas de fenêtre.": "Empty: “whole contract period” when there is no period below.",
  "Du … au …, une ligne par période. Aucune fenêtre : le trajet circule toute l'année.": "From … to …, one line per period. No period: the route runs all year.",
  "Décoché, le trajet est masqué. Les services déjà saisis, leurs factures et leurs vouchers ne changent pas.": "Unticked, the route is hidden. Existing bookings, their invoices and their vouchers do not change.",
  "Ce trajet est utilisé par {n} service. Le supprimer retirerait à ce service ses horaires et son billet. Masquez-le plutôt : il ne sera plus proposé et ce qui existe ne change pas.": "This route is used by {n} booking. Deleting it would remove that booking's times and ticket. Hide it instead: it will no longer be offered and nothing that exists changes.",
  "Ce trajet est utilisé par {n} services. Le supprimer retirerait à ces services leurs horaires et leur billet. Masquez-le plutôt : il ne sera plus proposé et ce qui existe ne change pas.": "This route is used by {n} bookings. Deleting it would remove those bookings' times and tickets. Hide it instead: it will no longer be offered and nothing that exists changes.",
