  // Lot C2 (17.11.2026) : paiements, écart soldé, réactivation, fusion de clients, hôtel qui suit, ligne enfant.
  "Fusionner deux fiches du même client": "Merge two records of the same client",
  "Les dossiers de l'autre fiche passent sur celle qu'on garde, puis l'autre fiche disparaît. Sans ce droit, la fusion demande « Supprimer un client » et « Créer et modifier les dossiers ».": "The other record's files move to the one you keep, then the other record is removed. Without this right, merging needs “Delete a client” and “Create and edit files”.",
  "Fusion impossible : les deux fiches doivent être deux clients différents de la même entreprise.": "Merge not possible: the two records must be two different clients of the same company.",
  "Votre rôle ne permet pas de fusionner des clients.": "Your role does not allow merging clients.",
  "Fusion réservée aux rôles qui voient tous les dossiers de l'entreprise.": "Merging is reserved for roles that see all the company's files.",
  "{n} service à venir part encore de l'ancien hôtel ({noms}). Mettre son lieu de pickup à « {nouveau} » ? Le voucher et la feuille du jour suivront.": "{n} upcoming service still starts from the old hotel ({noms}). Set its pickup place to “{nouveau}”? The voucher and the day sheet will follow.",
  "{n} services à venir partent encore de l'ancien hôtel ({noms}). Mettre leur lieu de pickup à « {nouveau} » ? Les vouchers et la feuille du jour suivront.": "{n} upcoming services still start from the old hotel ({noms}). Set their pickup place to “{nouveau}”? The vouchers and the day sheet will follow.",
