  "Champs vides repris de l'autre fiche : {champs}.": "Empty fields taken from the other record: {champs}.",
  "Les coordonnées de cette fiche restent telles quelles.": "This record's contact details stay as they are.",
  "Ses notes s'ajoutent à celles de cette fiche.": "Its notes are added to this record's notes.",
  "La fiche de {autre} est ensuite supprimée.": "The record of {autre} is then deleted.",
  "L'autre fiche a un dossier dans la corbeille ({refs}) : restaurez-le (Réglages, corbeille) avant la fusion.": "The other record has a file in the bin ({refs}): restore it (Settings, bin) before merging.",
  "Fiches fusionnées : {nom} garde tous les dossiers.": "Records merged: {nom} keeps all the files.",
  "La base n'a pas encore la fusion des clients : la migration de fusion doit d'abord être appliquée.": "The database cannot merge clients yet: the merge migration must be applied first.",
  "Fusion impossible : {message}": "Merge not possible: {message}",
  "Fusionner avec une autre fiche": "Merge with another record",
  "Pour un client saisi deux fois. Cette fiche-ci est gardée ; ouvrez l'autre fiche si c'est elle que vous voulez garder.": "For a client entered twice. This record is kept; open the other record if that is the one you want to keep.",
  "Fusionner ici": "Merge here",
  "Rien n'est fusionné tout seul. « Fusionner ici » montre ce qui change avant de le faire.": "Nothing is merged automatically. “Merge here” shows what changes before doing it.",
  "Rien n'est fusionné tout seul : ouvrez l'autre fiche pour comparer. La fusion demande le droit « Fusionner deux fiches du même client ».": "Nothing is merged automatically: open the other record to compare. Merging needs the right “Merge two records of the same client”.",
  "Le même client saisi deux fois : ses dossiers passent sur cette fiche, puis l'autre fiche disparaît.": "The same client entered twice: their files move to this record, then the other record is removed.",
  "Fusionner avec…": "Merge with…",
  "Ajoutez l'indicatif du pays au téléphone du client, par exemple +41, +33 ou +66, à la place du 0 du début.": "Add the country code to the client's phone, for example +41, +33 or +66, instead of the leading 0.",
  "Téléphone du client illisible : écrivez-le avec son indicatif, par exemple +41 79 123 45 67.": "The client's phone cannot be read: write it with its country code, for example +41 79 123 45 67.",
  "{n} réservation réactivée. Le prestataire n'est pas prévenu par l'outil.": "{n} booking reactivated. The tool does not notify the supplier.",
  "{n} réservations réactivées. Les prestataires ne sont pas prévenus par l'outil.": "{n} bookings reactivated. The tool does not notify the suppliers.",
  "Une réservation n'a pas pu être réactivée : {message}": "A booking could not be reactivated: {message}",
