  // Noms et marques à l'écran (migration 44).
  "Pour la personne à la saisie des vouchers : un formulaire, l'aperçu du voucher et l'envoi de l'image à la personne responsable. Avec le droit « Préparer et envoyer les factures pour la fiduciaire », un second onglet ouvre ces factures. Ni menu, ni autres écrans.": "For the person entering vouchers: a form, the voucher preview and sending the image to the person in charge. With the right “Prepare and send the invoices for the accountant”, a second tab opens these invoices. No menu, no other screens.",
  "Voix de l'assistant IA": "AI assistant voice",
  "Personne responsable": "Person in charge",
  "{role} : voit toutes les entreprises et gère les accès": "{role}: sees all companies and manages access",
  "Administration de l'organisation": "Organisation administrator",
  "Le lien « Ask on WhatsApp » ouvre la conversation avec {responsable}.": "The “Ask on WhatsApp” link opens the chat with {responsable}.",
