  "WhatsApp de {responsable} (reçoit les vouchers saisis)": "{responsable}'s WhatsApp (receives the entered vouchers)",
  "Avec l'indicatif. Sur ordinateur, l'image est copiée et cette conversation s'ouvre ; sur téléphone, un bouton ouvre la conversation après l'envoi de l'image. Vide : la personne à la saisie choisit {responsable} dans WhatsApp.": "With the country code. On a computer, the image is copied and this chat opens; on a phone, a button opens the chat after the image is sent. Empty: the person entering vouchers picks {responsable} in WhatsApp.",
  "Numéro de {licence}": "{licence} number",
  "Son intitulé (« {intitule} ») se change dans « Textes du voucher ».": "Its label (“{intitule}”) is changed in “Voucher texts”.",
  "En haut de la Booking confirmation. Sans photo, celle du modèle par défaut.": "At the top of the Booking confirmation. Without a photo, the default one.",
  "Automatique : la première administratrice": "Automatic: the first administrator",
  "Son prénom apparaît dans les textes de l'outil : « prévenez … », le WhatsApp qui reçoit les vouchers saisis.": "Their first name appears in the tool's texts: “let … know”, the WhatsApp that receives the entered vouchers.",
