  "Quelqu'un de ce client s'est déjà connecté : son administrateur règle la suite lui-même (« Mot de passe oublié » sur l'écran de connexion).": "Someone from this client has already signed in: their administrator takes it from here (“Forgot password” on the sign-in screen).",
  "Le lien n'a pas pu être créé. Réessayez dans un moment.": "The link could not be created. Try again in a moment.",
  "À envoyer au client sans l'ouvrir vous-même : ce lien connecte à son compte.": "Send it to the client without opening it yourself: this link signs in to their account.",
