  "Envoyez ce message à {nom}. Il remplace le lien précédent.": "Send this message to {nom}. It replaces the previous link.",
  "Personne de ce client ne s'est encore connecté et sa première entreprise n'est pas installée. Choisissez son type d'activité et sa devise, puis envoyez-lui le nouveau lien.": "No one from this client has signed in yet and their first business is not set up. Choose their type of business and currency, then send them the new link.",
  "Personne de ce client ne s'est encore connecté. Un nouveau lien remplace le précédent pour {email}.": "No one from this client has signed in yet. A new link replaces the previous one for {email}.",
  "Installer et créer le lien": "Set up and create the link",
