  "Liste des clients indisponible : {message}": "Client list unavailable: {message}",
  "Client déjà en service ou suspendu : son administrateur règle la suite": "Client already in use or suspended: their administrator takes it from here",
  "Rôles invalides": "Invalid roles",
  "Le lien ne sert qu'une fois et expire vite : envoyez-le tout de suite. Expiré ? « Reprendre » dans la liste des clients en crée un nouveau, tant que le client ne s'est pas connecté.": "The link works once and expires soon: send it right away. Expired? “Resume” in the client list creates a new one, as long as the client has not signed in.",
  // Fiches clients partagées (migration 46).
  "Ce client appartient à une autre entreprise qui ne partage pas ses clients avec celle-ci.": "This client belongs to another business that does not share its clients with this one.",
  "Seule l'administration utilise les clients d'une autre entreprise.": "Only administrators use another business's clients.",
  "Ce client a des dossiers : il ne change pas d'entreprise.": "This client has files: they cannot move to another business.",
  "Seule l'administration rattache un client à la fiche d'une autre entreprise.": "Only administrators link a client to another business's record.",
  "Réservé à l'administration générale, entre deux entreprises de l'organisation.": "Reserved for the organisation administrator, between two businesses of the organisation.",
  "{cible} trouve maintenant les clients de {source}.": "{cible} now finds the clients of {source}.",
  "{cible} ne trouve plus les clients de {source}. Les dossiers déjà créés gardent leur client.": "{cible} no longer finds the clients of {source}. Files already created keep their client.",
  "La base n'a pas encore le partage des clients : la migration 46 doit d'abord être appliquée.": "The database does not have client sharing yet: migration 46 must be applied first.",
  "Fiches clients partagées": "Shared client records",
  "Une entreprise peut partager ses fiches clients avec une autre : la même fiche sert alors dans les dossiers des deux, sans copie, et un changement se voit des deux côtés. Le partage va dans un seul sens. Seule l'administration choisit ces clients ; les autres rôles voient seulement le nom du client sur leurs dossiers. Les dossiers, montants et réglages restent à chaque entreprise.": "A business can share its client records with another: the same record is then used in the files of both, with no copy, and a change shows on both sides. Sharing goes one way only. Only administrators choose these clients; other roles only see the client's name on their files. Files, amounts and settings stay with each business.",
  "{source} partage ses clients avec": "{source} shares its clients with",
  "(partage déjà ses clients avec {source})": "(already shares its clients with {source})",
  "Fiche de {entreprise}, partagée : un changement se voit des deux côtés.": "{entreprise} record, shared: a change shows on both sides.",
  "Adresse (fiche {sigle})": "Address ({sigle} record)",
  "L'adresse de la fiche {sigle}. Le lieu de pickup se note sur chaque service.": "The address of the {sigle} record. The pick-up place is entered on each service.",
  "Cette fiche est rattachée à la fiche {sigle} de {garde} : une seule fiche pour les deux entreprises.": "This record is linked to the {sigle} record of {garde}: one record for both businesses.",
  "Ce client a sa fiche dans une autre entreprise. Son nom figure sur vos dossiers et vos vouchers ; ses coordonnées sont réservées à l'administration.": "This client's record is in another business. Their name appears on your files and vouchers; their contact details are reserved for administrators.",
  "Fiche de {source}, partagée avec {ici}. Un changement fait ici se voit aussi dans {source}. Seuls les dossiers de {ici} apparaissent ici.": "{source} record, shared with {ici}. A change made here also shows in {source}. Only {ici} files appear here.",
  "Dans les autres entreprises": "In the other businesses",
  "La même fiche sert dans ces dossiers. Lecture seule ici : ouvrez le dossier pour le modifier dans son entreprise.": "The same record is used in these files. Read-only here: open the file to change it in its business.",
