  "Supprimer cette liaison de ferry ?": "Delete this ferry link?",
  "Un trajet dont un seul bout est sur l'île passe par sa liaison : route jusqu'au port, ferry (durée fixe, traversée et attente comprises), route depuis le port en face. Les durées entre les ports et les lieux se mettent dans « En voiture ».": "A trip with only one end on the island uses its link: road to the port, ferry (fixed duration, crossing and waiting included), road from the opposite port. Durations between ports and places go under “By car”.",
