  "La brochure est trop longue pour une seule lecture : envoyez-la en deux fois.": "The brochure is too long for one reading: send it in two parts.",
  "« {nom} » : le prix rendu ne figure pas dans le texte imprimé, la ligne est marquée illisible.": "“{nom}”: the price returned is not in the printed text, the line is marked unreadable.",
  "« {nom} » : un net non imprimé a été retiré. Un net n'est jamais déduit.": "“{nom}”: a net price that is not printed was removed. A net price is never inferred.",
