  "Un horaire sans lieu de départ ou d'arrivée a été laissé de côté.": "A timetable line without a departure or arrival place was left out.",
  "La brochure compte plus de lignes qu'une lecture n'en prend : vérifiez la fin, ou envoyez-la en deux fois.": "The brochure has more lines than one reading takes: check the end, or send it in two parts.",
