  "{n} illisible": "{n} unreadable",
  "{n} illisibles": "{n} unreadable",
  "La brochure porte le nom « {nom} » : vérifiez que c'est bien celle de {partenaire}.": "The brochure bears the name “{nom}”: check that it is really the one from {partenaire}.",
  "Prix imprimés en {devise} : la base de prix compte en THB, vérifiez avant d'enregistrer.": "Prices printed in {devise}: the price list counts in THB, check before saving.",
  "{n} ligne lue": "{n} line read",
  "{n} lignes lues": "{n} lines read",
  "Cochez ce que vous gardez. Les prix de vente suivent la brochure ; les textes déjà remplis au catalogue ne changent pas ; un net n'est écrit que s'il est imprimé.": "Tick what you keep. Selling prices follow the brochure; texts already filled in the price list do not change; a net price is saved only if it is printed.",
  "Horaires de bateau": "Boat timetables",
  "{n} ligne du catalogue absente de la brochure : rien n'y change": "{n} price list line missing from the brochure: nothing changes in it",
  "{n} lignes du catalogue absentes de la brochure : rien n'y change": "{n} price list lines missing from the brochure: nothing changes in them",
  "Envoyez la photo, la capture ou le PDF de la brochure de {partenaire}. L'assistant relève les tarifs et les horaires imprimés ; vous choisissez ensuite ce qui entre dans le catalogue.": "Send the photo, screenshot or PDF of the brochure from {partenaire}. The assistant picks out the printed rates and timetables; you then choose what goes into the price list.",
  "Les fichiers partent chez Anthropic pour être lus, rien d'autre : ni le catalogue, ni les nets de la base. Envoyez la brochure publique, pas une grille de prix nets. Six fichiers au plus.": "The files go to Anthropic to be read, nothing else: neither the price list nor the stored net prices. Send the public brochure, not a net rate sheet. Six files at most.",

  // Suivi de l'assistant (20.11.2026)
  "Touchez une colonne pour lire ses chiffres.": "Tap a column to read its figures.",
  "Lire un message": "Read a message",
