  "Réussi": "Succeeded",
  "Refusé par Claude": "Refused by Claude",
  "Réponse rejetée par les contrôles": "Reply rejected by the checks",
  "Réponse coupée (trop longue)": "Reply cut off (too long)",
  "Pas de réponse utilisable": "No usable reply",
  "Recherche web interrompue": "Web search interrupted",
  "Anthropic occupé": "Anthropic busy",
