  "Erreur d'Anthropic": "Anthropic error",
  "{montant} $": "${montant}",
  "Coût aujourd'hui": "Cost today",
  "Coût du mois": "Cost this month",
  "Échecs du mois": "Failures this month",
  "Limite du jour": "Daily limit",
  "Réponses sans retouche": "Replies sent unchanged",
  "Somme du coût estimé des appels du jour (heure de Bangkok), d'après les jetons notés dans le journal et le prix du modèle qui a répondu. La facture d'Anthropic fait foi.": "Sum of the estimated cost of today's calls (Bangkok time), from the tokens recorded in the log and the price of the model that answered. Anthropic's invoice is the reference.",
  "Somme du coût estimé des appels depuis le 1er du mois. La projection prolonge le coût moyen par jour écoulé jusqu'à la fin du mois, à partir du 3 du mois.": "Sum of the estimated cost of calls since the 1st of the month. From the 3rd of the month, the projection extends the average cost per elapsed day to the end of the month.",
  "Appels qui n'ont rien rendu d'utilisable : refus de Claude, réponse coupée ou rejetée par les contrôles, clé refusée, Anthropic occupé ou en panne. Les demandes arrêtées avant Claude (assistant éteint, droit manquant, limite du jour atteinte) ne sont pas notées dans le journal.": "Calls that returned nothing usable: refused by Claude, reply cut off or rejected by the checks, key refused, Anthropic busy or down. Requests stopped before Claude (assistant off, missing right, daily limit reached) are not recorded in the log.",
  "Chaque personne a droit à un nombre fixe d'appels par jour (heure de Bangkok), toutes entreprises confondues. Au-delà, l'assistant refuse et la lecture par règles reste affichée. Cet écran ne compte que les appels des entreprises que vous suivez : pour une personne qui travaille aussi ailleurs, la limite peut être atteinte plus tôt.": "Each person has a fixed number of calls per day (Bangkok time), across all businesses. Beyond it, the assistant refuses and the rule-based reading stays on screen. This screen only counts calls from the businesses you follow: for a person who also works elsewhere, the limit may be reached sooner.",
  "À la copie d'une réponse rédigée par l'assistant, l'outil note la part de mots changés avant la copie, jamais le texte. La tuile donne la part des réponses copiées telles quelles. Une retouche faite ensuite dans WhatsApp n'est pas vue.": "When a reply drafted by the assistant is copied, the tool records the share of words changed before copying, never the text. The tile shows the share of replies copied as they were. An edit made afterwards in WhatsApp is not seen.",
  "Le suivi de l'assistant est réservé aux administratrices d'une entreprise.": "Assistant monitoring is reserved for a business's administrators.",
  "Toutes les entreprises": "All businesses",
  "Le journal de l'assistant n'existe pas encore dans la base (migration 27).": "The assistant log does not exist in the database yet (migration 27).",
  "Impossible de lire le journal de l'assistant : {message}": "Unable to read the assistant log: {message}",
