  "Personne n'a utilisé l'assistant ce mois-ci.": "Nobody used the assistant this month.",
  "Par entreprise": "By business",
  "Appels refusés ou en erreur": "Refused or failed calls",
  "Aucun échec ce mois-ci.": "No failures this month.",
  "Les {n} derniers sur 30 jours": "The last {n} over 30 days",
  "Les demandes arrêtées avant Claude (assistant éteint, droit manquant, limite du jour atteinte) ne sont pas notées dans le journal.": "Requests stopped before Claude (assistant off, missing right, daily limit reached) are not recorded in the log.",
  "Qualité des réponses rédigées": "Quality of drafted replies",
  "La mesure démarre avec la mise à jour 51 de la base : à chaque copie d'une réponse rédigée, l'outil notera la part de mots changés, jamais le texte. {n} réponses rédigées ce mois-ci.": "Measurement starts with database update 51: each time a drafted reply is copied, the tool will record the share of words changed, never the text. {n} replies drafted this month.",
  "{part} % des réponses copiées telles quelles ({n} sur {m}). En moyenne {moyenne} % des mots changés avant la copie.": "{part}% of replies copied as they were ({n} of {m}). On average {moyenne}% of words changed before copying.",
  "{r} réponses rédigées ce mois-ci, {m} copiées depuis l'outil.": "{r} replies drafted this month, {m} copied from the tool.",
  "Aucune réponse rédigée copiée ce mois-ci ({n} rédigées).": "No drafted reply copied this month ({n} drafted).",
  "Suivi de l'assistant : coût, usage et qualité": "Assistant monitoring: cost, usage and quality",
  "Onglet Assistant (conversation)": "Assistant tab (conversation)",
  "Échange trop long, arrêté": "Exchange too long, stopped",
  "Enregistrer confirme la durée. L'assistant s'en sert quand OpenStreetMap ne donne rien ; il prend toujours la marge conseillée.": "Saving confirms the duration. The assistant uses it when OpenStreetMap gives nothing; it always uses the advised margin.",
  "Les durées de référence de zone à zone. L'assistant prend d'abord OpenStreetMap ; la table sert quand OpenStreetMap ne trouve pas un lieu, ainsi que pour la marge conseillée. Une ligne « à vérifier » n'est confirmée qu'une fois enregistrée par vous.": "Reference durations from area to area. The assistant uses OpenStreetMap first; the table is used when OpenStreetMap cannot find a place, as well as for the advised margin. A line “to check” is confirmed only once you save it.",
  "Oublier les itinéraires calculés": "Forget calculated routes",
  "Effacer les lieux et les itinéraires déjà trouvés par OpenStreetMap ? Ils seront recherchés à nouveau au prochain calcul. La table n'est pas touchée.": "Clear the places and routes already found by OpenStreetMap? They will be looked up again at the next calculation. The table is not touched.",
  "Lieux et itinéraires effacés.": "Places and routes cleared.",
  "Crédit Anthropic épuisé": "Anthropic credit used up",
  "Le plafond du mois de l'assistant est atteint : il reprend le 1er du mois prochain, ou plus tôt si l'administration relève le plafond.": "The assistant's monthly cap is reached: it resumes on the 1st of next month, or sooner if the administrator raises the cap.",
  "Le crédit Anthropic de l'assistant est épuisé : l'administration doit le recharger. Le reste de l'outil marche normalement.": "The assistant's Anthropic credit is used up: the administrator needs to top it up. The rest of the tool works as usual.",
  "Le plafond du mois de l'assistant est atteint ({depense} dépensés sur {plafond}). Il reprend le {jour}, ou plus tôt si l'administration relève le plafond dans « Suivi de l'assistant ».": "The assistant's monthly cap is reached ({depense} spent out of {plafond}). It resumes on {jour}, or sooner if the administrator raises the cap in “Assistant monitoring”.",
  "Correction notée : l'assistant s'en servira la prochaine fois.": "Correction noted: the assistant will use it next time.",
  "{n} corrections notées : l'assistant s'en servira la prochaine fois.": "{n} corrections noted: the assistant will use them next time.",
  "Crédit du mois": "Credit this month",
  "Dépense estimée de tout l'assistant depuis le 1er du mois (heure de Bangkok), toutes entreprises confondues, face au plafond réglé par l'administratrice générale. À partir du seuil, les administratrices reçoivent une notification ; au plafond, l'assistant s'arrête jusqu'au 1er du mois suivant. La facture d'Anthropic fait foi.": "Estimated spending of the whole assistant since the 1st of the month (Bangkok time), all companies together, against the cap set by the main administrator. From the threshold on, administrators get a notification; at the cap, the assistant stops until the 1st of the next month. Anthropic's invoice is the reference.",
  "Le plafond du mois s'installe avec la mise à jour 54 de la base.": "The monthly cap comes with database update 54.",
  "Part du plafond dépensée": "Share of the cap spent",
  "{cout} sur {plafond}": "{cout} of {plafond}",
  "Plafond atteint : l'assistant est arrêté jusqu'au 1er du mois prochain.": "Cap reached: the assistant is stopped until the 1st of next month.",
  "{pct} % du plafond, alerte à {seuil} %, reste {reste}": "{pct}% of the cap, alert at {seuil}%, {reste} left",
  "Le plafond va de 1 à 1 000 $.": "The cap goes from $1 to $1,000.",
  "L'alerte se règle entre 50 et 99 %.": "The alert can be set between 50 and 99%.",
  "Plafond du mois enregistré.": "Monthly cap saved.",
  "Plafond du mois ($)": "Monthly cap ($)",
  "Alerte à (%)": "Alert at (%)",
  "Le crédit API se recharge dans la console Anthropic : le plafond protège ce crédit, il ne le remplace pas.": "API credit is topped up in the Anthropic console: the cap protects that credit, it does not replace it.",
  "Crédit de l'assistant": "Assistant credit",
  "Ce que l'assistant a appris": "What the assistant has learned",
  "Les apprentissages de l'assistant s'installent avec la mise à jour 54 de la base.": "The assistant's learning comes with database update 54.",
  "Oublier cette correction ? L'assistant ne s'en servira plus.": "Forget this correction? The assistant will no longer use it.",
  "Oublier": "Forget",
  "Correction oubliée.": "Correction forgotten.",
  "Quand une proposition de l'assistant est changée avant d'être validée, la correction est gardée pour l'entreprise et relue comme exemple dans les conversations suivantes. Jamais un net ni les coordonnées d'un client : les noms, téléphones et e-mails sont masqués.": "When a proposal from the assistant is changed before being approved, the correction is kept for the company and read again as an example in later conversations. Never a net price or a client's contact details: names, phone numbers and e-mails are masked.",
  "Aucune correction pour l'instant.": "No correction yet.",
  "Plafond du mois de l'assistant atteint ({cout} sur {plafond}) : l'assistant est arrêté jusqu'au 1er du mois prochain.": "The assistant's monthly cap is reached ({cout} of {plafond}): the assistant is stopped until the 1st of next month.",
  "L'assistant a dépensé {pct} % du plafond du mois ({cout} sur {plafond}).": "The assistant has spent {pct}% of the monthly cap ({cout} of {plafond}).",
  "Régler le plafond": "Set the cap",
  "Reste ce mois-ci : {reste}": "Left this month: {reste}",
  "{reste} restant": "{reste} left",
  "plafond atteint": "cap reached",
  "Voir le suivi": "See monitoring",
