  "L'assistant relit les fichiers, recopie les prix imprimés et les compare au catalogue. Vous cochez ce qui entre ; rien n'est écrit avant « Enregistrer ».": "The assistant reads the files again, copies the printed prices and compares them with the catalogue. You tick what goes in; nothing is written before “Save”.",
