  "Lire et comparer": "Read and compare",
  "Je prépare l'import de la brochure": "Preparing the brochure import",
  "Brochure à importer": "Brochure to import",
  "Créez d'abord le partenaire": "Create the partner first",
  "L'assistant relit les fichiers joints à la conversation et les compare aux tarifs de {partenaire}. Vous choisissez ensuite ce qui entre dans le catalogue.": "The assistant reads the files attached to the conversation again and compares them with the rates of {partenaire}. You then choose what goes into the catalogue.",
  "L'assistant relit les fichiers joints à la conversation : nouveau partenaire, contacts imprimés, tarifs et horaires. Vous choisissez ensuite ce qui entre dans le catalogue.": "The assistant reads the files attached to the conversation again: new partner, printed contacts, rates and timetables. You then choose what goes into the catalogue.",
